const stdout = $json.stdout || '';
const max = parseInt($env.RETRY_MAX, 10) || 200;
const windowHours = parseInt($env.RETRY_WINDOW_HOURS, 10) || 24;
const cutoff = Date.now() - windowHours * 3600 * 1000;

const byKey = {};
for (const line of stdout.split('\n')) {
  const t = line.trim();
  if (!t) continue;
  let l;
  try { l = JSON.parse(t); } catch (e) { continue; }
  if (!l || !l.repo) continue;
  const ts = l.ts ? new Date(l.ts).getTime() : Date.now();
  if (Number.isNaN(ts) || ts < cutoff) continue;
  byKey[l.pipeline + ':' + l.repo] = l;
}

const runId = 'retry-' + Date.now();
const items = Object.values(byKey).slice(-max).map((l) => {
  const safeName = String(l.repo).replace(/[^A-Za-z0-9._-]/g, '-');
  const pipeline = l.pipeline === 'internal' ? 'internal' : 'transit';
  const chunkId = 'retry-' + pipeline + '-' + safeName;
  const chunk = {
    chunkId,
    runId,
    pipeline,
    repos: [{ name: l.repo, url: l.url || '', target: l.target || '' }],
  };
  return { json: { ...chunk, chunkBase64: Buffer.from(JSON.stringify(chunk)).toString('base64') } };
});

if (items.length === 0) return [{ json: { noRetries: true } }];
return items;

const items = $input.all();
return [{
  json: {
    enqueued: items.length,
    pipelines: [...new Set(items.map((i) => i.json.pipeline))],
    at: new Date().toISOString(),
  },
}];
